class BowlingGame:
    """Keep track of the score of a game of bowling.

    - ``roll(pins)`` is called each time the player rolls a ball.
    - ``score()`` is called at the end of the game and returns the total.
    """

    MAX_FRAMES = 10

    def __init__(self):
        self._frames = []      # list of completed frames (each a list of rolls)
        self._current = []     # rolls in the current (in-progress) frame
        self._rolls = []       # flat list of all rolls so far
        self._over = False     # True once the 10th frame is complete

    # ------------------------------------------------------------------
    # rolling
    # ------------------------------------------------------------------
    def roll(self, pins):
        if self._over or len(self._frames) >= self.MAX_FRAMES:
            raise Exception("Cannot roll after game is over")
        if not 0 <= pins <= 10:
            raise Exception("Pin count exceeds pins on the lane")

        if len(self._frames) < self.MAX_FRAMES - 1:
            self._roll_regular_frame(pins)
        else:
            self._roll_last_frame(pins)

    def _roll_regular_frame(self, pins):
        if self._current:
            if self._current[0] + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
            self._current.append(pins)
            self._complete_frame()
        else:
            self._current.append(pins)
            if pins == 10:
                self._complete_frame()

    def _roll_last_frame(self, pins):
        cur = self._current
        n = len(cur)
        if n == 0:
            cur.append(pins)
        elif n == 1:
            if cur[0] != 10 and cur[0] + pins < 10:
                # open frame: game ends with no bonus rolls
                cur.append(pins)
                self._complete_frame()
            else:
                # strike or spare: more bonus roll(s) still required
                cur.append(pins)
        elif n == 2:
            if cur[0] == 10 and cur[1] != 10 and cur[1] + pins > 10:
                raise Exception("Pin count exceeds pins on the lane")
            cur.append(pins)
            self._complete_frame()
        else:
            raise Exception("Cannot roll after game is over")

    def _complete_frame(self):
        self._frames.append(self._current)
        self._rolls.extend(self._current)
        self._current = []
        if len(self._frames) == self.MAX_FRAMES:
            self._over = True

    # ------------------------------------------------------------------
    # scoring
    # ------------------------------------------------------------------
    def score(self):
        if len(self._frames) < self.MAX_FRAMES:
            raise Exception("Score cannot be taken until the end of the game")

        rolls = self._rolls
        total = 0
        i = 0
        for frame in range(self.MAX_FRAMES):
            if frame == self.MAX_FRAMES - 1:
                # the 10th frame counts every roll in it
                total += sum(rolls[i:])
                break
            if rolls[i] == 10:
                # strike: 10 plus the next two rolls
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            else:
                total += rolls[i] + rolls[i + 1]
                if rolls[i] + rolls[i + 1] == 10:
                    # spare: plus the next roll
                    total += rolls[i + 2]
                i += 2
        return total

